package ca.yorku.eecs3311.coursepilot.application.dto;
import ca.yorku.eecs3311.coursepilot.domain.model.*; import java.time.*; import java.util.*;
public record StudyPlanResponse(Long id,Long courseId,LocalDate startDate,LocalDate targetDate,int availableMinutes,String strategy,List<Item> items){public StudyPlanResponse{items=List.copyOf(items);}public static StudyPlanResponse from(StudyPlan p){return new StudyPlanResponse(p.getId(),p.getCourse().getId(),p.getStartDate(),p.getTargetDate(),p.getAvailableMinutes(),p.getStrategy(),p.getItems().stream().map(i->new Item(i.getId(),i.getScheduledDate(),i.getActivity(),i.getMinutes(),i.isCompleted(),i.getActualMinutes())).toList());}public record Item(Long id,LocalDate date,String activity,int minutes,boolean completed,int actualMinutes){}}
